sys_script_include.script:
var WeatherUtils = Class.create();
WeatherUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getWeatherForDestination: function() {

        var destination = this.getParameter('sysparm_destination');

        if (!destination)
            return '';

        try {

            var rm = new sn_ws.RESTMessageV2('WeatherAPI', 'Default GET');

            rm.setStringParameterNoEscape('q', destination);
            rm.setStringParameterNoEscape('appid', '1b5c9d42971b5e89b3624438a7a40728');

            var response = rm.execute();

            return "Status: " + response.getStatusCode() +
                "\nBody: " + response.getBody();

            var result = JSON.parse(response.getBody());

            var weather = result.weather[0].description;
            var temp = (result.main.temp - 273.15).toFixed(1);

            return weather + ", " + temp + " °C";

        } catch (ex) {
            return ex.message;
        }
    },

    type: 'WeatherUtils'
});
